(7723146, 1271473, 67723, '<td valign="top">The low technical quality and digital noise are taking points off for me. The composition is confusing to me.</td>', 'The low technical quality and digital noise are taking points off for me. The composition is confusing to me.', '2022-07-08 21:51:59.000000', NULL, 1),
(7723147, 1271229, 67723, '<td valign="top">Kind of bland lighting for me. Neat balls of ice though.</td>', 'Kind of bland lighting for me. Neat balls of ice though.', '2022-07-08 21:52:41.000000', NULL, 1),
